select is(pg_temp.payload('31430adf-b11f-5f51-8f58-cb27f8156d28'::uuid), $expected${"title":"International Organisational Behaviour","body":"A foundational course examining how culture, defined as the collective programming of the mind, shapes organisational behaviour across borders. The course moves from core cultural frameworks (Hofstede, GLOBE, Trompenaars) through perception, motivation, personality, communication, team management, leadership, negotiation, HR practice, organisational structure, ethics, and future trends including global mobility and AI. Assumes introductory Organisational Behaviour and Management.","topics":[{"chapter":"1","description":"The Imperative for International OB — Culture, the Onion Model, Values vs Practices"},{"chapter":"2","description":"Cultural Frameworks I — Hofstede's Dimensions, Schwartz's Values, the Lewis Model"},{"chapter":"3","description":"Cultural Frameworks II — The GLOBE Study, Trompenaars' Dilemmas, the Meyer Culture Map"},{"chapter":"4","description":"Perception, Attribution, and Attitudes Across Cultures"},{"chapter":"5","description":"Motivation in Cross-Cultural Context — Maslow, Herzberg, Equity Theory"},{"chapter":"6","description":"Personality and Cultural Intelligence (CQ) — The Big Five across cultures"},{"chapter":"7","description":"Communication Styles — High-Context vs Low-Context"},{"chapter":"8","description":"Managing Multicultural and Virtual Teams — Trust and Conflict"},{"chapter":"9","description":"Cross-Cultural Leadership — Universal vs Culturally-Contingent Perspectives"},{"chapter":"10","description":"Cross-Cultural Negotiation and Decision-Making"},{"chapter":"11","description":"International Human Resource Management — Expatriate Selection and Culture Shock"},{"chapter":"12","description":"Organisational Structure, Culture and Change — Pyramids, Machines, Markets, Families"},{"chapter":"13","description":"Ethics, CSR, and Sustainability in a Global Economy"},{"chapter":"14","description":"Course Integration and Future Trends — Global Mobility, Digital Nomads, and AI"}]}$expected$::jsonb,
  'BUA222: no Exam focus');
