select is(pg_temp.payload('88bb9b97-531e-513d-971f-6277d4e6223e'::uuid), $expected${"title":"Quantitative Analysis in Management","body":"A foundational course examining how mathematical and statistical techniques support evidence-based managerial decision-making. The course moves from core quantitative concepts (break-even analysis, revenue/cost/profit formulas) through data collection, descriptive and inferential statistics, correlation and regression, linear programming, and decision theory under risk and uncertainty. Assumes Business Statistics.","topics":[{"chapter":"1","description":"Week 1: Introduction to Quantitative Analysis in Management — Definition, Features, Importance, Areas of Application, Analytical Tools"},{"chapter":"2","description":"Week 2: Basic Mathematical Concepts for Management — Core Concepts, Revenue/Cost/Profit Formulas, Break-Even Analysis"},{"chapter":"3","description":"Week 3: Data Collection, Organization, and Presentation — Primary vs Secondary Data, Quantitative vs Qualitative, Charts and Graphs"},{"chapter":"4","description":"Week 4: Statistical Analysis for Management — Foundations of Statistics, Descriptive Statistics, the Normal Distribution, Hypothesis Testing, Confidence Intervals, ANOVA"},{"chapter":"5","description":"Week 5: Operational Modelling — Linear Programming, the Graphical Solution Method, Applications"},{"chapter":"6","description":"Week 6: Decision Theory and Managerial Decision-Making — Decision Environments, Criteria Under Uncertainty, EMV, Decision Trees"},{"chapter":"7","description":"Week 7: Analysis and Interpretation of Results — Data Analysis vs Interpretation, Correlation Analysis, Regression Analysis, Common Pitfalls"}],"formulaSheet":[{"name":"Break-Even Quantity (BEQ)","formula":"BEQ = FC / (P − v)","explanation":"The output level at which total revenue equals total cost — fixed cost divided by the contribution margin per unit.","example":"Selling Price = ₦5,000, Variable Cost = ₦3,000, Fixed Cost = ₦1,000,000; Contribution Margin = 5,000 − 3,000 = ₦2,000 per unit; BEQ = 1,000,000 / 2,000 = 500 units."},{"name":"Break-Even Revenue (BER)","formula":"BER = BEQ × P","explanation":"The sales revenue generated at the break-even point — break-even quantity multiplied by selling price."},{"name":"Total Revenue (TR)","formula":"TR = P × Q","explanation":"Total money earned from sales before deducting any cost — unit selling price times quantity sold.","example":"A company sells 2,500 units at ₦8,000 each: TR = 2,500 × ₦8,000 = ₦20,000,000."},{"name":"Total Cost (TC)","formula":"TC = FC + (v × Q)","explanation":"All costs combined — fixed cost plus the variable cost per unit times the number of units produced."},{"name":"Profit (π)","formula":"Profit = TR − TC = Q(P − v) − FC","explanation":"What remains after all costs: positive is a profit, negative is a loss — equivalently, contribution per unit times quantity, less fixed cost."},{"name":"Contribution Margin (CM)","formula":"CM = P − v","explanation":"The amount each unit sold contributes toward covering fixed costs (and then profit) — price minus variable cost per unit.","example":"Contribution Margin = 5,000 − 3,000 = ₦2,000 per unit."},{"name":"Average Cost (AC)","formula":"AC = TC / Q","explanation":"The cost per unit at a given output level — total cost divided by quantity."},{"name":"Marginal Cost (MC)","formula":"MC = change in TC / change in Q","explanation":"The cost of producing one additional unit — the change in total cost divided by the change in quantity."},{"name":"Target Profit Output","formula":"Target Profit Output = (FC + Target Profit) / (P − v)","explanation":"The number of units needed to reach a desired profit — fixed cost plus target profit, divided by contribution margin per unit.","example":"Target profit of ₦25,000 (FC = ₦45,000,000, P = ₦9,000, v = ₦6,000): Q = (45,000,000 + 25,000) / 3,000 = 15,009 units."},{"name":"Future Value (Compound Interest)","formula":"FV = P(1 + r)ⁿ","explanation":"The value of a present sum after n periods of compound growth at rate r per period.","example":"An investment of ₦1,000,000 growing at 10% annually for 3 years: FV = 1,000,000 × (1.10)³ = 1,000,000 × 1.331 = ₦1,331,000."},{"name":"Mean (x̄)","formula":"x̄ = Σ(x) / n","explanation":"The arithmetic average — the sum of all values divided by the number of values."},{"name":"Variance (s²)","formula":"s² = Σ(x − x̄)² / n","explanation":"The average of the squared deviations from the mean — a measure of how spread out the data is."},{"name":"Standard Deviation (s)","formula":"s = √[ Σ(x − x̄)² / n ]","explanation":"The square root of the variance — spread of the data in the same units as the data."},{"name":"Range","formula":"Range = Max − Min","explanation":"The simplest measure of spread — the largest value minus the smallest."},{"name":"Interquartile Range (IQR)","formula":"IQR = Q3 − Q1","explanation":"The spread of the middle 50% of the data — the third quartile minus the first quartile."},{"name":"Z-Score","formula":"Z = (X − μ) / σ","explanation":"How many standard deviations a value X lies from the mean — used with the normal distribution."},{"name":"Confidence Interval (CI)","formula":"CI = x̄ ± z × (σ / √(n))","explanation":"A range likely to contain the true population mean, at a chosen confidence level (z)."},{"name":"ANOVA F-Statistic","formula":"F = MSB / MSW","explanation":"Tests whether the means of three or more groups differ — the ratio of Mean Square Between to Mean Square Within; reject H0 if F-calculated > F-critical."},{"name":"Linear Programming (Objective & Corner-Point Method)","formula":"Maximise / Minimise Z = cx + dy  (evaluate Z at each corner point of the feasible region)","explanation":"Optimise an objective subject to linear constraints; the optimum occurs at a corner (vertex) of the feasible region, found by evaluating Z at every corner.","example":"Maximise Z = 5x + 4y subject to 6x + 4y ≤ 24, x + 2y ≤ 6, x ≥ 0, y ≥ 0. Corner points: (0,0) → 0, (4,0) → 20, (3,1.5) → 21, (0,3) → 12. Optimal: x = 3, y = 1.5, Z = 21."},{"name":"Expected Monetary Value (EMV)","formula":"EMV = Σ [ P(state) × Payoff(state) ]","explanation":"The probability-weighted average payoff of a decision alternative; choose the alternative with the highest EMV.","example":"Large Plant: 0.6(200,000) + 0.4(−180,000) = ₦48,000; Small Plant: 0.6(100,000) + 0.4(−20,000) = ₦52,000 → build the Small Plant (highest EMV of ₦52,000)."},{"name":"Pearson's Correlation Coefficient (r)","formula":"r = Σ[(x − x̄)(y − ȳ)] / √{ Σ(x − x̄)² × Σ(y − ȳ)² }","explanation":"Measures the strength and direction of a linear relationship between two variables, from −1 to +1; correlation does not imply causation.","example":"n=5, Σx=15, Σy=28, Σx²=55, Σy²=190, Σxy=102: r = [5(102) − (15)(28)] / √{[5(55) − 15²][5(190) − 28²]} = [510 − 420] / √{[275 − 225][950 − 784]} = 90 / √(50 × 166) = 90 / √8300 = 90 / 91.10 ≈ 0.988 (strong positive relationship)."}]}$expected$::jsonb,
  'BUA204: no Exam focus');
