  from unnest(array['anon', 'authenticated', 'service_role']) r,
       unnest(array['private.owner_content_rule(text)', 'private.owner_content_rule_states(jsonb)', 'private.content_rule_source(text)']) f;
select ok(not has_table_privilege(r, t, 'select, insert, update, delete'), format('%s has no access to %s', r, t))
  from unnest(array['anon', 'authenticated', 'service_role']) r,
       unnest(array['private.content_rules', 'private.content_rule_chunks']) t;
select is((select count(*)::integer from public.managed_content_items where created_by = '00000000-0000-4000-8000-000000000042'
  and kind = 'note' and published_revision is not null), 0, 'no seeded note is published');
select * from finish();
rollback;
